/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.text.DecimalFormat;import java.text.SimpleDateFormat;import java.util.ArrayList;import java.util.Arrays;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.util.StringUtils;import page2020.Data;import page2020.View;import page2020.anno.ColItem;import page2020.anno.Table2020;import page2020.anno.TableProp;import page2020.data.TableData;import page2020.unit.Upaging;import page2020.util.EmptyUtil;import page2020.view.C3;import page2020.view.bs4.B4data;import page2020.view.bs4.B4datalist;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4table;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3bg.X;import page2020.view.css3.C3box.Side;import page2020.view.css3.C3color.White;import page2020.view.css3.C3font.Weight;import page2020.view.css3.C3show.Cursor;import page2020.view.html5.H5td;import page2020.view.html5.H5th;public class Table extends B4table {	private static Logger log = LoggerFactory.getLogger(Table.class);	private static final String tableActive = "active";	private static final String tableBatch = "batch";	private static final String tableRow = "row";	private static final String tableApi = "api";	private static final String tableVertical = "vertical";	private static final String columnActiveColor = "active-color";	private static final String columnDatalist = "datalist";	private static final String columnErase = "erase";	private static final String serial_width = "2rem";	private TableProp prop;	private Table2020 anno;	private boolean jsp;	private boolean decorated;	private boolean container;	private Box box = null;	private boolean save = false;	private boolean caption;	private String color;	private boolean serial;	private boolean fill;	private String height;	private String width;		private String activeColor;	private int pageNum = 0;	private Upaging paging;	private int code = -1;	private boolean datatableJS = false;	private boolean operateJS = false;	private boolean pagingJS = false;	private boolean verticalJS = false;	private List<B4datalist> datalists = new ArrayList<B4datalist>();	private View view = new View();	private DataTable datatable;	private DecimalFormat[] decimalFormats;	private SimpleDateFormat[] dateFormats;	private Map<Integer, LinkedHashMap<String, Object>> datalistMap;	public Table(Class<?> clazz, String alias) {		super();		TableProp prop = new TableProp(clazz, alias);		if (prop.getAnno() != null) {			this.prop = prop;		} else {			return;		}		Table2020 anno = this.prop.getAnno();		this.anno = anno;		this.jsp = anno.jsp();		this.decorated = anno.decorated();		this.container = anno.container();		this.caption = anno.caption();		this.color = anno.color();		this.activeColor = anno.activeColor();		this.serial = anno.serial();		this.fill = anno.fill();		this.width = anno.width();		this.height = anno.height();		this.pageNum = (anno.paging() >= 0) ? anno.paging() : 0;		this.pagingJS = (this.pageNum > 0) ? true : false;		if (EmptyUtil.is(this.box) && EmptyUtil.not(anno.box())) {			this.box(anno.box());		}		if (EmptyUtil.not(alias)) {			super.name(alias);		} else {			super.name(this.prop.getName());		}		super.data(tableActive, anno.active());		super.data(tableBatch, anno.batch());		super.data(tableRow, anno.row());		this.save = anno.save();		for (String key : this.prop.getData().keySet()) {			ColItem column = this.prop.getData().get(key);			if (Pattern.datalist.equals(column.getPattern())) {				super.data(columnDatalist, true);				break;			}		}		String operate = StringUtils.trimAllWhitespace(anno.operate());		if (EmptyUtil.not(operate)) {			super.data(PageKey.operate, operate);			operateJS = true;		}		String vertical = StringUtils.trimAllWhitespace(anno.vertical());		if (EmptyUtil.not(vertical)) {			super.data(tableVertical, vertical);			super.data(tableBatch, true);			super.cssClass(D.none);					this.decorated = false;					this.verticalJS = true;			this.datatableJS = false;			this.pagingJS = false;		}  		super.cssClass(TextX.nowrap).css(C3.width("100%"), C3.margin("0"));		if (this.prop.getData2020() != null) {			this.datatable = new DataTable(super.getName(), this.prop.getData2020());		}		if (Log.table) {			log.info(this.logAttr("columns", this.prop.count()));		}	}	public Table(Class<?> clazz) {		this(clazz, null);	}	public Table automate(int ui, int code) {		if (! (this.operateJS || this.verticalJS)) {			if (this.code < 0) {				this.code = code;				} else {				code = this.code;				}		} else {			this.code = Code.inline;			code = Code.inline;			this.decorated = false;					this.color = "";					}		super.data(PageKey.code, code);				if (code == Code.row) {			super.data(columnActiveColor, this.activeColor);			super.css(C3.show.cursor(Cursor.pointer));		} else {			super.data(columnActiveColor, "");		}		if (this.decorated) {			this.decorated(ui);		}		if (this.serial) {			if (this.decorated) {				this.serial();			}			if (this.datatableJS) {				this.datatable.serial();			}		}		this.dataColumns(code);		this.head(code);		if (EmptyUtil.not(this.color)) {			super.cssClass(this.color);			super.getThead().cssClass(this.color);			if (this.datatableJS) {				this.view.selector("table[data-name='" + this.getName() + "']>thead th[data-i]",					C3.bg(B4table.hex(this.color))				);			}		}				super.append(new B4data());		if (this.pagingJS && this.pageNum > 0) {			super.cssClass(D.none, Name.PageKey.paging);			this.paging = new Upaging(super.getName(), this.pageNum, this.view);		}		if (Log.table) {			log.info("Table('" + super.getName() + "'): automate(" + code + ")");		}		return this;	}	public Table code(int code) {		this.code = code;		if (Log.data) {			log.info("Table('" + super.getName() + "'): code('" + code + "')");		}		return this;			}	public TableData data(List<?> source, Data data) {		Object obj = source.get(0);		int type = 0;			if (obj instanceof Map<?, ?>) {			type = 1;			} else if (obj instanceof List<?>) {			type = 2;			}		if (this.jsp) {			if (this.datatableJS && this.datatable.isProcess()) {				this.jsp = false;			}		}		int count = this.prop.count();		boolean patterns[] = new boolean[count];		this.decimalFormats = new DecimalFormat[count];		this.dateFormats = new SimpleDateFormat[count];		this.datalistMap = new LinkedHashMap<Integer, LinkedHashMap<String, Object>>();		for (int i=0; i < count; i++) {			ColItem item = this.prop.value(i);			patterns[i] = false;			LinkedHashMap<String, Object> map = null;			String datalistKey = null;			if (EmptyUtil.not(item.getPattern())) {				switch (item.getPattern()) {				case Pattern.number:					this.decimalFormats[i] = new DecimalFormat(item.getFormat());					patterns[i] = true;					break;				case Pattern.date:				case Pattern.time:				case Pattern.datetime:					this.dateFormats[i] = new SimpleDateFormat(item.getFormat());					patterns[i] = true;					break;				case Pattern.datalist:					datalistKey = EmptyUtil.not(item.getAnno().datalist()) ? 							item.getAnno().datalist() : item.getName();					map = data.value(datalistKey);					if (map != null) {						this.datalistMap.put(i, map);						patterns[i] = true;					}					break;				}			}		}		List<String> keys = new ArrayList<String>();		List<List<Object>> buffer = new ArrayList<List<Object>>();		List<String> rowAttrs = new ArrayList<String>();			Map<?, ?> map = null;		List<?> list = null;		int index = 0;			for (Object object : source) {			List<String> keyList = new ArrayList<String>();			List<Object> valueList = new ArrayList<Object>();			if (type == 1) {				map = (Map<?, ?>) object;			} else if (type == 2) {				list = (List<?>) object;			}			if (this.serial) {				valueList.add(index + 1);				}			for (int i=0; i < count; i++) {				ColItem item = this.prop.value(i);								Object value = null;				if (type == 1) {					value = map.get(item.getFieldName());				} else if (type == 2) {					value = list.get(i);				} else {					try {						value = item.getField().get(object);					} catch (Exception ex) {						value = null;					}				}				if (item.isKey()) {					keyList.add(value.toString());				}				if (! item.isHidden()) {					if (EmptyUtil.not(value)) {						if (patterns[i]) {							valueList.add(this.pattern(i, item, value));						} else if (item.isWrap()) {							valueList.add(((String) value)								.replaceAll("\n", "")								.replaceAll("\r", "<br>"));						} else {							valueList.add(value);						}					} else {						valueList.add("");						}				}			}			if (this.fill) {				valueList.add("");			}			String key = keyList.isEmpty() ? String.valueOf(index) : 					StringUtils.collectionToCommaDelimitedString(keyList);			keys.add(key);			if (this.jsp) {				rowAttrs.add(" data-key=\"" + key + "\"");			}			buffer.add(valueList);			index += 1;		}		if (this.jsp) {			B4data b4data = (B4data) super.find(null, "tbody", null);			b4data.setAttr(rowAttrs);			b4data.setData(buffer);		}		this.decimalFormats = null;		this.dateFormats = null;		this.datalistMap = null;		if (Log.data) {			log.info("Table('" + super.getName() + "'): data(" + buffer.size() + ")");		}		return new TableData(keys, buffer);	}	public Table decorated(boolean decorated) {		this.decorated = decorated;		if (Log.table) {			log.info(this.logAttr("decorated", decorated));		}		return this;			}	public Table container(boolean container) {		this.container = container;		if (Log.table) {			log.info(this.logAttr("container", container));		}		return this;			}	public Table box(String argument) {		this.container = false;		this.box = new Box(argument);		return this;	}	public Table box() {		this.box(null);		return this;	}	@Override	public Table hide(boolean hidden) {		if (hidden) {			super.cssClass(D.none);		} else if (super.hasClass(D.none)) {			super.removeClass(D.none);		}		if (Log.table) {			log.info(this.logAttr("hide", hidden));		}		return this;			}	public Table active(boolean active) {		super.data(tableActive, active);		if (Log.data) {			log.info(this.logAttr("active", active));		}		return this;	}	public Table batch(boolean batch) {		super.data(tableBatch, batch);		if (Log.table) {			log.info(this.logAttr("batch", batch));		}		return this;			}	public Table row(boolean row) {		super.data(tableRow, row);		if (Log.table) {			log.info(this.logAttr("row", row));		}		return this;		}	public Table operate(String operate) {		String value = StringUtils.trimAllWhitespace(operate);		if (EmptyUtil.not(value)) {			super.data(PageKey.operate, value);			operateJS = true;		} else {			super.removeData(PageKey.operate);			operateJS = false;		}		if (Log.table) {			log.info(this.logAttr("operate", value));		}		return this;	}	public Table save(boolean save) {		this.save = save;		if (Log.table) {			log.info(this.logAttr("save", save));		}		return this;	}	public Table datatable() {		if (this.datatable != null) {			this.datatableJS = true;					super.data(tableApi, true);			}		if (Log.table) {			log.info(this.logAttr("datatable", this.datatableJS));		}		return this;			}	public DataTable argument() {		this.datatable();			return this.datatable;	}	public Table process(String... dataButtons) {		this.datatable();		if (this.datatableJS) {			this.datatable.process(true);			if (EmptyUtil.not(dataButtons)) {				this.datatable.buttons(dataButtons);			}			if (Log.table) {				log.info(this.logAttr("process", true));			}		}		return this;	}	public Table proxy(int length) {		this.datatable();		if (this.datatableJS) {			this.datatable.proxy(length);			if (Log.table) {				log.info(this.logAttr("proxy", length));			}		}		return this;	}	public Table paging(int number) {		this.pageNum = (number >= 0) ? number : 0;		this.pagingJS = (this.pageNum > 0) ? true : false;		this.pageNum = number;		this.pagingJS = true;		if (Log.table) {			log.info(this.logAttr("paging", number));		}		return this;			}	public Table vertical(String function) {		String vertical = (String) super.getData(tableVertical);		if (EmptyUtil.not(vertical)) {			vertical += ";" + function;		}		super.data(tableVertical, vertical);		if (Log.table) {			log.info(this.logAttr("vertical", function));		}		return this;			}	public Table caption(boolean caption) {		this.caption = caption;		if (Log.table) {			log.info(this.logAttr("caption", caption));		}		return this;	}	public Table color(String color) {		this.color = color;		if (Log.table) {			log.info(this.logAttr("headerColor", color));		}		return this;			}	public Table activeColor(String color) {		this.activeColor = color;		if (Log.table) {			log.info(this.logAttr("activeColor", color));		}		return this;			}	public Table serial(boolean serial) {		this.serial = serial;		if (Log.table) {			log.info(this.logAttr("serial", serial));		}		return this;	}	public Table fill(boolean fill) {		this.fill = fill;		if (Log.table) {			log.info(this.logAttr("fill", fill));		}		return this;			}	public Table width(String pixels) {		this.width = pixels;		if (Log.table) {			log.info(this.logAttr("width", pixels));		}		return this;			}	public Table height(String pixels) {		this.height = pixels;		if (Log.table) {			log.info(this.logAttr("height", pixels));		}		return this;			}	public Table hidden(String... fields) {		if (EmptyUtil.not(fields) && this.prop != null) {			Arrays.asList(fields).forEach(field -> {				ColItem item = this.prop.itemByField(field);				if (item != null) {					item.setHidden(true);				}			});			if (Log.table) {				log.info(this.logAttr("hidden", Arrays.asList(fields).toString()));			}		} else {			log.error("hidden: argument(fields) has empty !");		}		return this;	}	public Table color(String field, String color) {		if (EmptyUtil.not(field, color) && this.prop != null) {			ColItem item = this.prop.itemByField(field);			if (item != null) {				item.setColor(color);				if (Log.table) {					log.info(this.logColumn(field, "color", color));				}						}		} else {			log.error("color: argument(field, color) has empty !");		}		return this;	}	public Table background(String field, String color) {		if (EmptyUtil.not(field, color) && this.prop != null) {			ColItem item = this.prop.itemByField(field);			if (item != null) {				item.setBackground(color);				if (Log.table) {					log.info(this.logColumn(field, "background", color));				}						}		} else {			log.error("background: argument(field, color) has empty !");		}		return this;			}	public Table bold(String... fields) {		if (EmptyUtil.not(fields) && this.prop != null) {			Arrays.asList(fields).forEach(field -> {				ColItem item = this.prop.itemByField(field);				if (item != null) {					item.setBold(true);				}			});			if (Log.table) {				log.info(this.logAttr("bold", Arrays.asList(fields).toString()));			}					} else {			log.error("bold: argument(fields) is empty !");		}		return this;	}	public Table italic(String... fields) {		if (EmptyUtil.not(fields) && this.prop != null) {			Arrays.asList(fields).forEach(field -> {				ColItem item = this.prop.itemByField(field);				if (item != null) {					item.setItalic(true);				}			});			if (Log.table) {				log.info(this.logAttr("italic", Arrays.asList(fields).toString()));			}					} else {			log.error("bold: argument(fields) is empty !");		}		return this;	}	public Table width(String field, String pixels) {		if (EmptyUtil.not(field, pixels) && this.prop != null) {			ColItem item = this.prop.itemByField(field);			if (item != null) {				item.setWidth(pixels);				if (Log.table) {					log.info(this.logColumn(field, "width", pixels));				}						}		} else {			log.error("width: argument(field, pixels) has empty !");		}		return this;	}	public Table align(String field, int align) {		if (EmptyUtil.not(field) && this.prop != null) {			ColItem item = this.prop.itemByField(field);			if (item != null) {				item.setAlign(align);				if (Log.table) {					log.info(this.logColumn(field, "align", align));				}						}		} else {			log.error("align: argument(field) is empty !");		}		return this;	}	@Override	public Table copy() {		Table table = (Table) super.copy();		if (this.datalists.size() > 0) {			List<B4datalist> datalists = new ArrayList<B4datalist>();			this.datalists.forEach(b4datalist -> {				datalists.add(b4datalist.copy());			});			table.setDatalists(datalists);		} 		table.setView(this.view.copy());		if (this.datatable != null) {			table.setDatatable(this.datatable.copy());		}		if (this.paging != null) {			table.setPaging(this.paging.copy());		}		return table;	}	private void decorated(int ui) {		boolean bBordered = this.anno.bordered();		boolean bBorderless = this.anno.borderless();		boolean bStriped = this.anno.striped();		if (ui > 0) {			bBordered = false;			bBorderless = true;			bStriped = true;		}		super.cssClass(table);				if (this.anno.small()) {			super.cssClass(small);		}		if (bBorderless) {			super.cssClass(borderless);		}		if (bBordered) {			super.cssClass(bordered);		}		if (bStriped) {			super.cssClass(striped);		}		if (this.anno.hover()) {			super.cssClass(hover);		}	}	private void serial() {		String bgHex = B4table.hex(this.color);				String column = "table[data-name='" + super.getName() + "']>%s>tr>%s[data-i='0']";		this.view.selector(String.format(column, "thead", "th"),			C3.bg(bgHex), C3.width("1rem")		);		this.view.selector(String.format(column, "tbody", "td"),			C3.bg(bgHex), 			C3.color(White.White), 			C3.font.weight(Weight.bold), 			C3.text.align(Side.center)		);	}	private void dataColumns(int code) {		String table = "table[data-name='" + super.getName() + "']";		String th1 = table + ">thead>tr>th[data-i='";		String td1 = table + ">tbody>tr>td[data-i='";		String end = "']";		this.view.selector(table + ">tbody", C3.bg(White.White));		int index = 0;		if (this.serial) {			index = 1;		}		int count = this.prop.count();		for (int i=0; i < count; i++) {			ColItem item = this.prop.value(i);			if (item.isHidden()) {				continue;			}			String td = td1 + index + end;			String th = th1 + index + end;			if (EmptyUtil.not(item.getColor())) {				this.view.selector(td, C3.color(item.getColor()));			}			if (EmptyUtil.not(item.getBackground())) {				this.view.selector(td, C3.bg(item.getBackground()));			}			if (item.isBold()) {				this.view.selector(td, C3.font.weight(Weight.bold));			}			if (item.isItalic()) {				this.view.selector(td, C3.font.italic(true));			}			if (EmptyUtil.not(this.width) || EmptyUtil.not(item.getWidth())) {				String pixels = EmptyUtil.not(item.getWidth()) ? item.getWidth() : this.width;				this.view.selector(th, C3.width(pixels));				}			int align = this.anno.align();			if (align < 0 && item.getAlign() >= 0) {				align = item.getAlign();			}			if (align == 1) {				this.view.selector(td, C3.text.align(X.right));			} else if (align == 2) {				this.view.selector(td, C3.text.align(X.center));			}			index += 1;		}					}	private void head(int code) {		super.thead();		int index = 0;		if (this.serial) {			H5td column = super.column().data("i", 0);			if (! this.isDatatableJS()) {				column.css(C3.width(serial_width));			}			index = 1;		}		int count = this.prop.count();		for (int i=0; i < count; i++) {			ColItem item = this.prop.value(i);			if (item.isHidden()) {				continue;			}			H5th th = super.column(App.fieldKey(item.getClassName(), item.getFieldName()));			th.data("i", index++);			if (Pattern.datalist.equals(item.getPattern())) {				String name = EmptyUtil.not(item.getAnno().datalist()) ? 					item.getAnno().datalist() : item.getName();				th.data(columnDatalist, name);				this.datalists.add(new B4datalist(name, item.getAnno().reverse()));			}			if (EmptyUtil.not(item.getErase())) {				th.data(columnErase, item.getErase());			}		}		if (this.fill) {			super.column();		}	}	private Object pattern(int index, ColItem item, Object oldValue) {		String newValue = null;		switch (item.getPattern()) {		case Pattern.number:			try {				newValue = this.decimalFormats[index].format(oldValue).toString();				if (EmptyUtil.not(item.getDollar())) {					newValue = item.getDollar() + newValue;				}			} catch (Exception ex) {				newValue = null;			}			break;		case Pattern.date:		case Pattern.time:		case Pattern.datetime:			try {				newValue = this.dateFormats[index].format(oldValue);			} catch (Exception ex) {				newValue = null;			}			break;		case Pattern.datalist:			try {				newValue = (String) this.datalistMap.get(index).get(oldValue.toString());			} catch (Exception ex) {				newValue = null;			}			break;		}		if (newValue != null) {			return newValue;		} else {			return oldValue;		}	}	private String logAttr(String attribute, Object value) {		return String.format("Table('%s'): %s=%s", super.getName(), attribute, value.toString());	}	private String logColumn(String columnName, String attribute, Object value) {		return String.format("Column('%s'): %s=%s", columnName, attribute, value.toString());	}	public TableProp getProp() {		return prop;	}	public boolean isJsp() {		return jsp;	}	public boolean isDecorated() {		return decorated;	}	public boolean isContainer() {		return container;	}	public Box getBox() {		return box;	}	public boolean isCaption() {		return caption;	}	public String getHeight() {		return height;	}	public boolean isSerial() {		return serial;	}	public Upaging getPaging() {		return paging;	}	public void setPaging(Upaging paging) {		this.paging = paging;	}	public int getCode() {		return code;	}	public boolean isDatatableJS() {		return datatableJS;	}	public boolean isOperateJS() {		return operateJS;	}	public boolean isPagingJS() {		return pagingJS;	}	public boolean isVerticalJS() {		return verticalJS;	}	public List<B4datalist> getDatalists() {		return datalists;	}	public void setDatalists(List<B4datalist> datalists) {		this.datalists = datalists;	}	public View getView() {		return view;	}	public void setView(View view) {		this.view = view;	}	public DataTable getDatatable() {		return datatable;	}	public void setDatatable(DataTable datatable) {		this.datatable = datatable;	}	public boolean isSave() {		return save;	}}